def run():
    wb = openpyxl.load_workbook(THING_FILE)
    ws = wb['Thing']
    headers = {ws.cell(1, c).value: c for c in range(1, ws.max_column+1)}

    det_c = headers['detail']
    det_en_c = headers['detail_EN']
    
    count = 0
    for r in range(2, ws.max_row+1):
        en = ws.cell(r, det_en_c).value
        if en and str(en).strip() in DETAILS_IT:
            ws.cell(r, det_c, DETAILS_IT[str(en).strip()])
            count += 1

    wb.save(THING_FILE)
    print(f"Applied {count} detail translations to Thing.xlsx")

if __name__ == '__main__':
    run()
